choose.when:
SELECT id AS "id", logistics_date AS "scheduleDate", (SELECT cln.name FROM clients cln WHERE cln.client_code = production_schedule.client_code LIMIT 1) AS "clientName", (SELECT CASE WHEN pdn.spec IS NOT NULL AND pdn.spec != '' THEN pdn.name || '(' || pdn.spec || ')' ELSE pdn.name END FROM products pdn WHERE pdn.code = production_schedule.product_code) AS "productName", COALESCE(logistics_actual_qty, actual_qty, order_qty) AS "orderQty", COALESCE((SELECT ci.item_nm FROM tb_common_code_item ci JOIN tb_common_code_group cg ON cg.common_code_group_id = ci.group_id AND cg.group_code = 'VEHICLE_INFO' JOIN tb_tenant ct ON ct.tenant_id = cg.tenant_id AND ct.tenant_code = 'SONGYEON' WHERE ci.item_code = ship_vehicle LIMIT 1), ship_vehicle) AS "vehicle", COALESCE((SELECT ci.item_nm FROM tb_common_code_item ci JOIN tb_common_code_group cg ON cg.common_code_group_id = ci.group_id AND cg.group_code = 'PACKING_TYPE' JOIN tb_tenant ct ON ct.tenant_id = cg.tenant_id AND ct.tenant_code = 'SONGYEON' WHERE ci.item_code = ship_packing_method LIMIT 1), ship_packing_method) AS "packingMethod", ship_note AS "shipNote", visit_order AS "visitOrder", (SELECT emp.name FROM employees emp WHERE emp.id = driver_id LIMIT 1) AS "driverName" FROM production_schedule WHERE ship_confirmed = 1 AND logistics_date BETWEEN #{start} AND #{end}
AND (SELECT CASE WHEN pdn.spec IS NOT NULL AND pdn.spec != '' THEN pdn.name || '(' || pdn.spec || ')' ELSE pdn.name END FROM products pdn WHERE pdn.code = production_schedule.product_code) ILIKE '%' || #{productName} || '%'
AND (SELECT cln.name FROM clients cln WHERE cln.client_code = production_schedule.client_code LIMIT 1) ILIKE '%' || #{clientName} || '%'

choose.otherwise:
SELECT id AS "id", schedule_date AS "scheduleDate", (SELECT cln.name FROM clients cln WHERE cln.client_code = logistics_schedule.client_code LIMIT 1) AS "clientName", (SELECT CASE WHEN pdn.spec IS NOT NULL AND pdn.spec != '' THEN pdn.name || '(' || pdn.spec || ')' ELSE pdn.name END FROM products pdn WHERE pdn.code = logistics_schedule.product_code) AS "productName", COALESCE(actual_qty, order_qty) AS "orderQty", COALESCE((SELECT ci.item_nm FROM tb_common_code_item ci JOIN tb_common_code_group cg ON cg.common_code_group_id = ci.group_id AND cg.group_code = 'VEHICLE_INFO' JOIN tb_tenant ct ON ct.tenant_id = cg.tenant_id AND ct.tenant_code = 'SONGYEON' WHERE ci.item_code = vehicle LIMIT 1), vehicle) AS "vehicle", COALESCE((SELECT ci.item_nm FROM tb_common_code_item ci JOIN tb_common_code_group cg ON cg.common_code_group_id = ci.group_id AND cg.group_code = 'PACKING_TYPE' JOIN tb_tenant ct ON ct.tenant_id = cg.tenant_id AND ct.tenant_code = 'SONGYEON' WHERE ci.item_code = packing_method LIMIT 1), packing_method) AS "packingMethod", ship_note AS "shipNote", visit_order AS "visitOrder", (SELECT emp.name FROM employees emp WHERE emp.id = driver_id LIMIT 1) AS "driverName" FROM logistics_schedule WHERE ship_confirmed = 1 AND schedule_date BETWEEN #{start} AND #{end}
AND (SELECT CASE WHEN pdn.spec IS NOT NULL AND pdn.spec != '' THEN pdn.name || '(' || pdn.spec || ')' ELSE pdn.name END FROM products pdn WHERE pdn.code = logistics_schedule.product_code) ILIKE '%' || #{productName} || '%'
AND (SELECT cln.name FROM clients cln WHERE cln.client_code = logistics_schedule.client_code LIMIT 1) ILIKE '%' || #{clientName} || '%'
